import type { Learned, ProfessionId, Recipe } from './types';
import data from './recipes.json';

// recipes.json is generated by `npm run recipes` (scripts/recipes.mjs) as compact rows:
// [id, name, profession, skill, learned, makes?].
type Row = [number, string, ProfessionId, number, Learned, string?];

export const RECIPES: Recipe[] = (data as unknown as Row[]).map(([id, name, prof, skill, learned, makes]) =>
  makes ? { id, name, prof, skill, learned, makes } : { id, name, prof, skill, learned },
);

const byId = new Map(RECIPES.map((r) => [r.id, r]));

export function recipe(id: number): Recipe | undefined {
  return byId.get(id);
}

/** A recipe someone has to log: anything not taught by a trainer. */
export function isNotable(r: Recipe): boolean {
  return r.learned !== 'trainer';
}

function fold(text: string): string {
  return text.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').trim();
}

const folded = new Map(RECIPES.map((r) => [r.id, fold(r.makes ? `${r.name} ${r.makes}` : r.name)]));

/** Recipes matching what someone has typed so far, best first: names that start with it, then names
 *  with a word that starts with it, then names that contain it anywhere. Every typed word must match. */
export function searchRecipes(query: string, filter: (r: Recipe) => boolean = () => true, limit = 25): Recipe[] {
  const words = fold(query).split(/\s+/).filter(Boolean);
  const scored: { r: Recipe; score: number }[] = [];
  for (const r of RECIPES) {
    if (!filter(r)) continue;
    const text = folded.get(r.id)!;
    if (!words.every((w) => text.includes(w))) continue;
    const first = words[0] ?? '';
    const score = !first ? 2 : text.startsWith(first) ? 0 : ` ${text}`.includes(` ${first}`) ? 1 : 2;
    scored.push({ r, score });
  }
  scored.sort((a, b) => a.score - b.score || a.r.name.localeCompare(b.r.name));
  return scored.slice(0, limit).map((s) => s.r);
}

export function recipeLabel(r: Recipe): string {
  return r.makes && r.makes !== r.name ? `${r.name} → ${r.makes}` : r.name;
}
